from fastapi import FastAPI, Depends, Security
from fastapi.security import OAuth2PasswordBearer
import json

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

def dep_b():
    return "b"

def dep_a(b = Security(dep_b)):
    return "a"

@app.get("/path1", dependencies=[Security(dep_a, scopes=["scope1"])])
def path1():
    return "path1"

@app.get("/path2", dependencies=[Security(dep_b)])
def path2():
    return "path2"

openapi_schema = app.openapi()
print(json.dumps(openapi_schema["paths"], indent=2))

